//! CP-06D-R1: real native registry, ANSF origin, custody/effect journals.
//! Fixture-host confirmation is not installed native OS dialog acceptance.
use std::{collections::VecDeque,fs,path::{Path,PathBuf},sync::atomic::{AtomicBool,AtomicU64,Ordering},io::Read};
use lu_core::{ansf::AnsfStore,ansf_live_chat::{LiveEvent,LiveKind},conversation_authority::TrustedUserTurnVerifier,inference_host::Cancellation,journal::{EffectJournal,EffectState},model_custody_turn::{CustodyIntent,CustodyAction,CustodyProposal,ReviewedCustody},model_turn_journal::{ModelAuditKind as K,ModelTurnJournal},native_trash_custody::{CustodyState,TrashCustodyLedger},supervised_tool_generation::{ModelStepGenerator,NativeGenerationError}};
use serde_json::Value;
use sha2::{Digest,Sha256};
static SEQ:AtomicU64=AtomicU64::new(0);
const CHAT:&str="c-custody-000000000001";const T1:&str="g-00000000000000000000000000000001";const T2:&str="g-00000000000000000000000000000002";const CID:&str="ct-00000000000000000001";const E1:&str="effect-trash-0000000001";const E2:&str="effect-restore-00000001";const FILE:&str="source.txt";const BYTES:&[u8]=b"Original fixture content.\n";
const TRASH:&str="Trash the file source.txt";const RESTORE:&str="Restore the file source.txt";const TS:&str=r#"{"selection":"trash_file"}"#;const RS:&str=r#"{"selection":"restore_file"}"#;const DONE:&str=r#"{"status":"verified_completion"}"#;
fn event(n:u32,kind:LiveKind,turn:&str,text:&str)->LiveEvent{LiveEvent{event_id:format!("e-{n:032x}"),kind,text:text.into(),user_turn_id:(kind==LiveKind::User).then(||turn.into()),legacy_turn_id:None,generation_id:(kind!=LiveKind::User).then(||turn.into()),call_id:None,tool_id:None}}
struct Fixture{base:PathBuf,folder:PathBuf,book:AnsfStore,audit:ModelTurnJournal,effects:EffectJournal,ledger:TrashCustodyLedger,live:AtomicBool}
impl Fixture{
 fn new(base:Option<PathBuf>)->Self{let base=base.unwrap_or_else(||std::env::temp_dir().join(format!("lu-cp06dr1-{}-{}",std::process::id(),SEQ.fetch_add(1,Ordering::Relaxed))));fs::create_dir_all(&base).unwrap();let folder=base.join("approved");fs::create_dir(&folder).unwrap();fs::write(folder.join(FILE),BYTES).unwrap();let book=AnsfStore::open(&base.join("chat.sqlite")).unwrap();book.create_session(CHAT,"workspace","Custody").unwrap();book.start_chapter(CHAT,"Original").unwrap();let audit=ModelTurnJournal::open(&base.join("audit.sqlite")).unwrap();let effects=EffectJournal::open(&base.join("effects.sqlite")).unwrap();let ledger=TrashCustodyLedger::open(&base.join("custody.sqlite")).unwrap();Self{base,folder,book,audit,effects,ledger,live:AtomicBool::new(true)}}
 fn start(&self,turn:&str,request:&str){let n=if turn==T1{1}else{4};self.book.append_host_chat_event(CHAT,&event(n,LiveKind::User,turn,request)).unwrap();}
 fn verify(&self,turn:&str)->Result<(),String>{if self.live.load(Ordering::SeqCst)&&self.verify_user_turn(CHAT,turn){Ok(())}else{Err("Cancelled fixture".into())}}
 fn propose(&self,turn:&str,request:&str,m:&mut dyn ModelStepGenerator)->Result<Option<CustodyProposal>,String>{CustodyIntent::parse(request).unwrap().propose(CHAT,turn,self,m,&Cancellation::default(),&self.audit,&||self.verify(turn))}
 fn trash_review(&self,m:&mut dyn ModelStepGenerator)->ReviewedCustody{self.start(T1,TRASH);self.propose(T1,TRASH,m).unwrap().unwrap().review_trash(&self.folder.join(FILE),CID,E1,&self.audit).unwrap()}
 fn restore_review(&self,m:&mut dyn ModelStepGenerator)->ReviewedCustody{self.start(T2,RESTORE);self.propose(T2,RESTORE,m).unwrap().unwrap().review_restore(CID,E2,&self.ledger,&self.effects,&self.audit).unwrap()}
 fn finish(&self,t:&str,answer:&str){let n=if t==T1{2}else{5};self.book.append_host_chat_event(CHAT,&event(n,LiveKind::AssistantProgress,t,answer)).unwrap();self.book.append_host_chat_event(CHAT,&event(n+1,LiveKind::AssistantCompleted,t,"")).unwrap();assert_eq!(self.book.generation_terminal_kind(CHAT,t).unwrap(),Some(LiveKind::AssistantCompleted));}
 fn assert_verified(&self,turn:&str,action:CustodyAction,answer:&str,origin:&str){let id=if action==CustodyAction::Trash{E1}else{E2};let rows=self.audit.events_for(CHAT,turn).unwrap();assert!(rows.iter().all(|e|e.kind!=K::FinalAnswer));let feedback:Value=serde_json::from_str(&rows.iter().find(|e|e.kind==K::ToolFeedback).unwrap().payload).unwrap();let presentation:Value=serde_json::from_str(&rows.iter().find(|e|e.kind==K::EvidencePresentation).unwrap().payload).unwrap();let effect=self.effects.get(id).unwrap().unwrap();assert_eq!(effect.state,EffectState::Applied);let sha=format!("{:x}",Sha256::digest(effect.receipt.unwrap()));assert_eq!(feedback["receipt_sha256"],sha);assert_eq!(presentation["receipt_sha256"],sha);assert_eq!(presentation["origin"],origin);assert_eq!(presentation["answer"],answer);assert!(self.effects.independent_verified_receipt(id,action.native_id(),&sha).unwrap());let r=self.ledger.get(CID).unwrap().unwrap();assert_eq!(r.state,if action==CustodyAction::Trash{CustodyState::Trashed}else{CustodyState::Restored});let (present,absent)=if action==CustodyAction::Trash{(&r.trash_entry,&r.original)}else{(&r.original,&r.trash_entry)};assert_eq!(fs::read(self.folder.join(present)).unwrap(),BYTES);assert!(!self.folder.join(absent).exists());assert_eq!(ModelTurnJournal::open(&self.base.join("audit.sqlite")).unwrap().events_for(CHAT,turn).unwrap(),rows);assert_eq!(TrashCustodyLedger::open(&self.base.join("custody.sqlite")).unwrap().get(CID).unwrap().unwrap(),r);}
 fn cleanup(self){let p=self.base.clone();drop(self);fs::remove_dir_all(p).unwrap()}
 async fn make_trash(&self){let mut m=Scripted::new(&[TS,DONE]);let r=self.trash_review(&mut m);let o=r.execute(true,self,&self.ledger,&self.effects,&self.audit,&||self.verify(T1)).await.unwrap().unwrap();let a=o.present(&mut m,&Cancellation::default(),&self.audit,&self.effects,&self.ledger,&||self.verify(T1)).unwrap();self.finish(T1,&a)}
}
impl TrustedUserTurnVerifier for Fixture{fn verify_user_turn(&self,c:&str,t:&str)->bool{let original=if t==T1{TRASH}else if t==T2{RESTORE}else{return false};c==CHAT&&self.book.authenticated_chat_turn(c,t).ok().flatten().is_some_and(|v|v.0==original)&&self.book.latest_authenticated_chat_turn(c).ok().flatten().is_some_and(|v|v.0==t&&v.1==original)}}
struct Scripted(VecDeque<String>);impl Scripted{fn new(v:&[&str])->Self{Self(v.iter().map(|s|s.to_string()).collect())}}impl ModelStepGenerator for Scripted{fn generate_step(&mut self,_:&str,_:u32,_:&Cancellation)->Result<String,NativeGenerationError>{Ok(self.0.pop_front().expect("unexpected inference"))}}
#[test]fn exact_intent_and_inert_proposal(){for s in ["Delete the file source.txt","Trash the file ../source.txt","Trash the file source.txt and restore it","Trash the file source.txt without tools","Restore the file lu-trash-id.txt","Restore the file source.txt to /other","Permanently delete the file source.txt"]{assert!(CustodyIntent::parse(s).is_none(),"{s}")}for bad in [r#"{"selection":null}"#,RS,r#"{"selection":"trash_file","approved":true}"#,r#"{"selection":"trash_file","path":"other.txt"}"#]{let f=Fixture::new(None);f.start(T1,TRASH);assert!(f.propose(T1,TRASH,&mut Scripted::new(&[bad])).unwrap().is_none());assert!(f.folder.join(FILE).exists());assert!(f.ledger.get(CID).unwrap().is_none());assert!(f.effects.get(E1).unwrap().is_none());f.cleanup()}}
#[tokio::test]async fn confirmed_trash_and_restore_with_durable_fallback(){let f=Fixture::new(None);let mut m=Scripted::new(&[TS,DONE,RS,r#"{"status":"unverified"}"#]);let r=f.trash_review(&mut m);assert!(f.folder.join(FILE).exists());assert!(f.ledger.get(CID).unwrap().is_none());let o=r.execute(true,&f,&f.ledger,&f.effects,&f.audit,&||f.verify(T1)).await.unwrap().unwrap();let a=o.present(&mut m,&Cancellation::default(),&f.audit,&f.effects,&f.ledger,&||f.verify(T1)).unwrap();f.assert_verified(T1,CustodyAction::Trash,&a,"model_selected_verified_effect_host_rendered");f.finish(T1,&a);let r=f.restore_review(&mut m);assert!(!f.folder.join(FILE).exists());let o=r.execute(true,&f,&f.ledger,&f.effects,&f.audit,&||f.verify(T2)).await.unwrap().unwrap();let a=o.present(&mut m,&Cancellation::default(),&f.audit,&f.effects,&f.ledger,&||f.verify(T2)).unwrap();f.assert_verified(T2,CustodyAction::Restore,&a,"host_verified_effect_fallback");f.finish(T2,&a);assert!(f.ledger.validated_trash_receipt(CID,CHAT,&f.effects).is_err());f.cleanup()}
#[tokio::test]async fn refusal_stale_source_and_revoked_operation_do_not_dispatch(){for case in ["decline","changed","revoked","used-audit"]{let f=Fixture::new(None);let r=f.trash_review(&mut Scripted::new(&[TS]));if case=="changed"{fs::write(f.folder.join(FILE),b"changed").unwrap()}if case=="revoked"{f.live.store(false,Ordering::SeqCst)}if case=="used-audit"{f.audit.append(CHAT,T1,K::Rejected,"substituted",None).unwrap();}let o=r.execute(case!="decline",&f,&f.ledger,&f.effects,&f.audit,&||f.verify(T1)).await;if case=="decline"{assert!(o.unwrap().is_none())}else{assert!(o.is_err(),"{case}")}assert!(f.folder.join(FILE).exists());assert!(f.ledger.get(CID).unwrap().is_none());assert!(f.effects.get(E1).unwrap().is_none());f.cleanup()}}
#[tokio::test]async fn restore_collision_changed_custody_and_refusal(){for case in ["decline","collision","changed","wrong-owner"]{let f=Fixture::new(None);f.make_trash().await;if case=="wrong-owner"{assert!(f.ledger.validated_trash_receipt(CID,"foreign-chat-00001",&f.effects).is_err());f.cleanup();continue}let r=f.restore_review(&mut Scripted::new(&[RS]));let stored=f.ledger.get(CID).unwrap().unwrap().trash_entry;if case=="collision"{fs::write(f.folder.join(FILE),b"occupied").unwrap()}if case=="changed"{fs::write(f.folder.join(&stored),b"changed custody").unwrap()}let o=r.execute(case!="decline",&f,&f.ledger,&f.effects,&f.audit,&||f.verify(T2)).await;if case=="decline"{assert!(o.unwrap().is_none())}else{assert!(o.is_err(),"{case}")}assert_eq!(f.ledger.get(CID).unwrap().unwrap().state,CustodyState::Trashed);assert!(f.effects.get(E2).unwrap().is_none());assert!(f.folder.join(&stored).exists());if case=="collision"{assert_eq!(fs::read(f.folder.join(FILE)).unwrap(),b"occupied")}else{assert!(!f.folder.join(FILE).exists())}f.cleanup()}}
#[tokio::test]async fn post_effect_stop_does_not_publish_or_replay(){let f=Fixture::new(None);let mut m=Scripted::new(&[TS]);let r=f.trash_review(&mut m);let o=r.execute(true,&f,&f.ledger,&f.effects,&f.audit,&||f.verify(T1)).await.unwrap().unwrap();f.live.store(false,Ordering::SeqCst);assert!(o.present(&mut m,&Cancellation::default(),&f.audit,&f.effects,&f.ledger,&||f.verify(T1)).is_err());assert_eq!(f.ledger.get(CID).unwrap().unwrap().state,CustodyState::Trashed);assert_eq!(f.effects.get(E1).unwrap().unwrap().state,EffectState::Applied);assert!(f.audit.events_for(CHAT,T1).unwrap().iter().all(|r|r.kind!=K::EvidencePresentation&&r.kind!=K::FinalAnswer));f.book.append_host_chat_event(CHAT,&event(2,LiveKind::AssistantCancelled,T1,"")).unwrap();f.cleanup()}
fn hash(p:&Path)->String{let mut h=Sha256::new();let mut f=fs::File::open(p).unwrap();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
#[tokio::test]
#[ignore="requires pinned local llama-server, genuine GGUF and fixture-host confirmation"]
async fn cp06dr1_genuine_trash_restore_and_refusals(){
 use lu_core::{inference_supervisor::TrustedInferenceSupervisor,model_admission::ModelAdmissionManager,persistent_llama_backend::{PersistentEngineConfig,PersistentLlamaBackend},supervised_tool_generation::SupervisorModelStep};use std::{num::NonZeroUsize,time::Duration};
 let exe=PathBuf::from(std::env::var("LU_CP06D_SERVER").unwrap());let gguf=PathBuf::from(std::env::var("LU_CP06D_GGUF").unwrap());let esha=std::env::var("LU_CP06D_SERVER_SHA256").unwrap();let msha=std::env::var("LU_CP06D_GGUF_SHA256").unwrap();assert_eq!(hash(&exe),esha);assert_eq!(hash(&gguf),msha);let pin:[u8;32]=(0..esha.len()).step_by(2).map(|i|u8::from_str_radix(&esha[i..i+2],16).unwrap()).collect::<Vec<_>>().try_into().unwrap();let auth="deadbeef".repeat(8);
 let mut manager=ModelAdmissionManager::new();let admitted=manager.admit(gguf.parent().unwrap(),gguf.file_name().unwrap().to_str().unwrap()).unwrap().clone();let supervisor=TrustedInferenceSupervisor::new("llama-cpu".into(),8192,vec![("model-1".into(),admitted)],move||PersistentLlamaBackend::new(PersistentEngineConfig{executable:exe.clone(),expected_sha256:pin,threads:NonZeroUsize::new(3).unwrap(),context_tokens:8192,startup_timeout:Duration::from_secs(120),request_timeout:Duration::from_secs(120),api_key:auth.clone(),load_observer:None})).unwrap();let sid="cp06dr1-custody";supervisor.load("model-1",sid.into(),"custody-load").unwrap();let base=PathBuf::from(std::env::var("LU_CP06D_EVIDENCE").unwrap());
 for (i,(tag,trash_ok,restore_ok)) in [("roundtrip",true,true),("decline-trash",false,false),("decline-restore",true,false)].into_iter().enumerate(){let f=Fixture::new(Some(base.join(tag)));let mut m=SupervisorModelStep::new(&supervisor,sid.into(),format!("custody-{i}")).unwrap();let r=f.trash_review(&mut m);let o=r.execute(trash_ok,&f,&f.ledger,&f.effects,&f.audit,&||f.verify(T1)).await.unwrap();if let Some(o)=o{let a=o.present(&mut m,&Cancellation::default(),&f.audit,&f.effects,&f.ledger,&||f.verify(T1)).unwrap();f.assert_verified(T1,CustodyAction::Trash,&a,"model_selected_verified_effect_host_rendered");f.finish(T1,&a);let r=f.restore_review(&mut m);let o=r.execute(restore_ok,&f,&f.ledger,&f.effects,&f.audit,&||f.verify(T2)).await.unwrap();if let Some(o)=o{let a=o.present(&mut m,&Cancellation::default(),&f.audit,&f.effects,&f.ledger,&||f.verify(T2)).unwrap();f.assert_verified(T2,CustodyAction::Restore,&a,"model_selected_verified_effect_host_rendered");f.finish(T2,&a);}else{assert!(!restore_ok);assert!(f.effects.get(E2).unwrap().is_none());assert_eq!(f.ledger.get(CID).unwrap().unwrap().state,CustodyState::Trashed);f.finish(T2,"Restore declined. No file was changed.");}}else{assert!(!trash_ok);assert!(f.effects.get(E1).unwrap().is_none());assert!(f.ledger.get(CID).unwrap().is_none());assert!(f.folder.join(FILE).exists());f.finish(T1,"Trash declined. No file was changed.");}for turn in [T1,T2]{for e in f.audit.events_for(CHAT,turn).unwrap(){println!("CP06DR1 {tag} {turn} {:?} {}",e.kind,e.payload)}}println!("CP06DR1_PASS {tag}");}
 supervisor.unload(sid,"custody-unload").unwrap();assert!(supervisor.status().unwrap().pid.is_none());
}
